-- title: School
-- description: A small school: students, courses and enrollments. Best for your first queries.
--
-- Tables: students, courses, enrollments
-- This file is read-only sample data for the SQL Lab. The app copies it into a
-- practice database, so your experiments never change this file.
-- Generated by tools/generate_datasets.py

PRAGMA foreign_keys = ON;

CREATE TABLE students (
    id          INTEGER PRIMARY KEY,
    first_name  TEXT NOT NULL,
    last_name   TEXT NOT NULL,
    birth_date  TEXT NOT NULL,          -- dates are stored as 'YYYY-MM-DD' text in SQLite
    city        TEXT NOT NULL,
    email       TEXT,                   -- may be NULL (unknown)
    enrolled_on TEXT NOT NULL
);

CREATE TABLE courses (
    id         INTEGER PRIMARY KEY,
    title      TEXT NOT NULL UNIQUE,
    department TEXT NOT NULL,
    credits    INTEGER NOT NULL CHECK (credits > 0),
    teacher    TEXT                     -- NULL means no teacher assigned yet
);

CREATE TABLE enrollments (
    id         INTEGER PRIMARY KEY,
    student_id INTEGER NOT NULL REFERENCES students (id),
    course_id  INTEGER NOT NULL REFERENCES courses (id),
    term       TEXT NOT NULL,
    score      INTEGER CHECK (score BETWEEN 0 AND 100),  -- NULL = not graded yet
    grade      TEXT
);



